param([Parameter(Mandatory=$true)][string]$NodeExe,[Parameter(Mandatory=$true)][string]$BridgeRoot,[Parameter(Mandatory=$true)][string]$ConfigPath)
$ErrorActionPreference='Stop';$service='NalandaBiometricBridge';$node=(Resolve-Path -LiteralPath $NodeExe).Path;$root=(Resolve-Path -LiteralPath $BridgeRoot).Path;$config=(Resolve-Path -LiteralPath $ConfigPath).Path;$agent=Join-Path $root 'dist\agent.js';if(-not(Test-Path -LiteralPath $agent -PathType Leaf)){throw 'Build the bridge before service installation.'};$binary='"'+$node+'" "'+$agent+'"';if(Get-Service -Name $service -ErrorAction SilentlyContinue){throw 'Service already exists; use restart-service.ps1 or a governed upgrade.'};[Environment]::SetEnvironmentVariable('NALANDA_BIOMETRIC_BRIDGE_CONFIG',$config,'Machine');sc.exe create $service binPath= $binary start= auto DisplayName= 'Nalanda Biometric Bridge' | Out-Null;sc.exe failure $service reset= 86400 actions= restart/5000/restart/15000/restart/60000 | Out-Null;Start-Service -Name $service
